import { useCallback, useId, useMemo, useState } from 'react';
import type { KeyboardEvent } from 'react';
import { Button, Input } from '@jinx-ui/react';

export type TagPickerProps = {
  label?: string;
  placeholder?: string;
  hint?: string;
  defaultTags?: string[];
  maxTags?: number;
  onChange?: (tags: string[]) => void;
};

const SEPARATORS = [',', ';'];

export default function TagPicker({
  label = 'Теги статьи',
  placeholder = 'Введите тег и нажмите Enter',
  hint = 'Enter или запятая — добавить тег, Backspace — удалить последний',
  defaultTags = [],
  maxTags = 12,
  onChange,
}: TagPickerProps) {
  const [tags, setTags] = useState<string[]>(() =>
    defaultTags.map((tag) => tag.trim()).filter(Boolean).slice(0, maxTags),
  );
  const [draft, setDraft] = useState('');
  const inputId = useId();
  const hintId = useId();
  const listId = useId();

  const isFull = tags.length >= maxTags;

  const commit = useCallback(
    (next: string[]) => {
      setTags(next);
      onChange?.(next);
    },
    [onChange],
  );

  const addTag = useCallback(
    (raw: string) => {
      const value = raw.trim().replace(/\s+/g, ' ');
      if (!value || isFull) return;
      const exists = tags.some((tag) => tag.toLowerCase() === value.toLowerCase());
      if (exists) {
        setDraft('');
        return;
      }
      commit([...tags, value]);
      setDraft('');
    },
    [commit, isFull, tags],
  );

  const removeTag = useCallback(
    (target: string) => {
      commit(tags.filter((tag) => tag !== target));
    },
    [commit, tags],
  );

  const handleKeyDown = useCallback(
    (event: KeyboardEvent<HTMLInputElement>) => {
      if (event.key === 'Enter' || SEPARATORS.includes(event.key)) {
        event.preventDefault();
        addTag(draft);
        return;
      }
      if (event.key === 'Backspace' && draft.length === 0 && tags.length > 0) {
        event.preventDefault();
        removeTag(tags[tags.length - 1]);
      }
    },
    [addTag, draft, removeTag, tags],
  );

  const counter = useMemo(() => `${tags.length} / ${maxTags}`, [maxTags, tags.length]);

  return (
    <div
      className="jx-field jx-stack"
      style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-2)' }}
    >
      <label className="jx-label" htmlFor={inputId}>
        {label}
      </label>

      <Input
        id={inputId}
        className="jx-input"
        type="text"
        value={draft}
        placeholder={isFull ? 'Достигнут лимит тегов' : placeholder}
        disabled={isFull}
        aria-describedby={`${hintId} ${listId}`}
        onChange={(event) => setDraft(event.target.value)}
        onKeyDown={handleKeyDown}
        onBlur={() => addTag(draft)}
      />

      <p
        id={hintId}
        className="jx-hint"
        style={{
          display: 'flex',
          justifyContent: 'space-between',
          gap: 'var(--jx-space-2)',
          color: 'var(--jx-fg-muted)',
          fontSize: 'var(--jx-font-size-sm)',
          margin: 0,
        }}
      >
        <span>{hint}</span>
        <span aria-live="polite">{counter}</span>
      </p>

      <ul
        id={listId}
        className="jx-cluster"
        aria-label="Выбранные теги"
        style={{
          display: 'flex',
          flexWrap: 'wrap',
          gap: 'var(--jx-space-2)',
          listStyle: 'none',
          margin: 0,
          padding: 0,
          minHeight: 'var(--jx-space-6)',
        }}
      >
        {tags.length === 0 ? (
          <li
            className="jx-hint"
            style={{ color: 'var(--jx-fg-muted)', fontSize: 'var(--jx-font-size-sm)' }}
          >
            Пока ничего не выбрано
          </li>
        ) : (
          tags.map((tag) => (
            <li
              key={tag}
              className="jx-tag"
              style={{
                display: 'inline-flex',
                alignItems: 'center',
                gap: 'var(--jx-space-1)',
                paddingInline: 'var(--jx-space-2)',
                paddingBlock: 'var(--jx-space-1)',
                border: 'var(--jx-border-width) solid var(--jx-border)',
                borderRadius: 'var(--jx-radius)',
                background: 'var(--jx-surface)',
                color: 'var(--jx-fg)',
              }}
            >
              <span>{tag}</span>
              <Button
                type="button"
                size="sm"
                variant="ghost"
                aria-label={`Удалить тег ${tag}`}
                onClick={() => removeTag(tag)}
              >
                ×
              </Button>
            </li>
          ))
        )}
      </ul>
    </div>
  );
}

